<script setup>import {computed,ref} from 'vue';const p=defineProps({jobs:Array,masterJobs:Array});const emit=defineEmits(['add-job','remove-job']);const form=ref({date:new Date().toISOString().slice(0,10),typeId:'',qty:1}),search=ref('');const filtered=computed(()=>p.jobs.filter(j=>(j.master?.name||'').toLowerCase().includes(search.value.toLowerCase())||j.date.includes(search.value)));function submit(){if(!form.value.typeId||form.value.qty<1)return;emit('add-job',{date:form.value.date,typeId:Number(form.value.typeId),qty:Number(form.value.qty)});form.value={date:new Date().toISOString().slice(0,10),typeId:'',qty:1}}</script><template><section class="page-head"><div><span class="eyebrow">INPUT DATA</span><h1>Pekerjaan Teknisi</h1><p>Catat pekerjaan selesai untuk menghitung estimasi poin.</p></div></section><div class="content-grid"><section class="panel"><div class="panel-head"><div><span class="eyebrow">TRANSAKSI</span><h2>Tambah Pekerjaan</h2></div></div><form @submit.prevent="submit" class="form-grid"><label>Tanggal<input v-model="form.date" type="date" required></label><label>Jenis pekerjaan<select v-model="form.typeId" required><option value="">Pilih pekerjaan</option><option v-for="m in masterJobs" :key="m.id" :value="m.id">{{m.code}} — {{m.name}} ({{m.points}} poin)</option></select></label><label>Jumlah pekerjaan<input v-model.number="form.qty" type="number" min="1"></label><button class="btn-primary full">＋ Simpan Pekerjaan</button></form><div class="note-box">ℹ️ Bobot poin pada prototype adalah data demo. Sesuaikan melalui Master Pekerjaan.</div></section><section class="panel"><div class="panel-head"><div><span class="eyebrow">HISTORY</span><h2>Riwayat</h2></div><input class="search" v-model="search" placeholder="Cari..."></div><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Pekerjaan</th><th>Qty</th><th>Poin</th><th>Total</th><th></th></tr></thead><tbody><tr v-for="j in filtered" :key="j.id"><td>{{j.date}}</td><td><b>{{j.master?.name}}</b><small class="block">{{j.master?.code}}</small></td><td>{{j.qty}}</td><td>{{j.points}}</td><td><b class="neon">+{{j.total}}</b></td><td><button class="danger-icon" @click="emit('remove-job',j.id)">×</button></td></tr><tr v-if="!filtered.length"><td colspan="6" class="empty">Belum ada data.</td></tr></tbody></table></div></section></div></template>